import { useState } from 'react';
import './FormSurvey.css';

export default function FormSurvey() {
  const [surveyData, setSurveyData] = useState({
    name: '',
    email: '',
    age: '',
    satisfaction: '3',
    features: [],
    comments: ''
  });

  const featureOptions = [
    'User Interface',
    'Performance',
    'Customer Support',
    'Pricing',
    'Features'
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setSurveyData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleCheckboxChange = (feature) => {
    setSurveyData(prev => {
      const newFeatures = prev.features.includes(feature)
        ? prev.features.filter(f => f !== feature)
        : [...prev.features, feature];
      return {
        ...prev,
        features: newFeatures
      };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Survey submitted:', surveyData);
    // Submission logic here
  };

  return (
    <form onSubmit={handleSubmit} className="survey-form">
      <h3>Product Feedback Survey</h3>
      <p>Help us improve by sharing your experience with our product.</p>

      <div className="form-group">
        <label htmlFor="name">Your Name</label>
        <input
          type="text"
          id="name"
          name="name"
          value={surveyData.name}
          onChange={handleChange}
          placeholder="Jane Smith"
        />
      </div>

      <div className="form-group">
        <label htmlFor="email">Email (optional)</label>
        <input
          type="email"
          id="email"
          name="email"
          value={surveyData.email}
          onChange={handleChange}
          placeholder="jane.smith@example.com"
        />
      </div>

      <div className="form-group">
        <label htmlFor="age">Age Group</label>
        <select
          id="age"
          name="age"
          value={surveyData.age}
          onChange={handleChange}
        >
          <option value="">Select your age group</option>
          <option value="18-24">18-24</option>
          <option value="25-34">25-34</option>
          <option value="35-44">35-44</option>
          <option value="45-54">45-54</option>
          <option value="55+">55+</option>
        </select>
      </div>

      <div className="form-group">
        <label>Overall Satisfaction</label>
        <div className="rating-scale">
          <span>1 (Poor)</span>
          {[1, 2, 3, 4, 5].map(num => (
            <label key={num}>
              <input
                type="radio"
                name="satisfaction"
                value={String(num)}
                checked={surveyData.satisfaction === String(num)}
                onChange={handleChange}
              />
              {num}
            </label>
          ))}
          <span>5 (Excellent)</span>
        </div>
      </div>

      <div className="form-group">
        <label>Which features do you use most? (Select all that apply)</label>
        <div className="checkbox-group">
          {featureOptions.map(feature => (
            <label key={feature} className="checkbox-option">
              <input
                type="checkbox"
                checked={surveyData.features.includes(feature)}
                onChange={() => handleCheckboxChange(feature)}
              />
              {feature}
            </label>
          ))}
        </div>
      </div>

      <div className="form-group">
        <label htmlFor="comments">Additional Comments</label>
        <textarea
          id="comments"
          name="comments"
          value={surveyData.comments}
          onChange={handleChange}
          placeholder="What do you like most? What can we improve?"
          rows={4}
        />
      </div>

      <button type="submit" className="submit-btn">Submit Feedback</button>
    </form>
  );
}

