import React from 'react';
import './ProgressBar.css';

type ProgressBarProps = {
  value: number;
  max?: number;
  variant?: 'default' | 'thin' | 'rounded';
  color?: string;
};

const ProgressBar: React.FC<ProgressBarProps> = ({
  value,
  max = 100,
  variant = 'default',
  color = '#4CAF50',
}) => {
  const percentage = Math.min((value / max) * 100, 100);

  return (
    <div className={`progress-bar ${variant}`}>
      <div
        className="progress-bar-fill"
        style={{ width: `${percentage}%`, backgroundColor: color }}
      ></div>
      <span className="progress-bar-label">{`${Math.round(percentage)}%`}</span>
    </div>
  );
};

export default ProgressBar;

src/components/progress/ProgressCircle.t:
import React from 'react';
import './ProgressCircle.css';

type ProgressCircleProps = {
  value: number;
  max?: number;
  size?: number;
  strokeWidth?: number;
  color?: string;
};

const ProgressCircle: React.FC<ProgressCircleProps> = ({
  value,
  max = 100,
  size = 100,
  strokeWidth = 10,
  color = '#4CAF50',
}) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const percentage = Math.min((value / max) * 100, 100);
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className="progress-circle-container">
      <svg width={size} height={size} className="progress-circle">
        <circle
          className="progress-circle-bg"
          cx={size / 2}
          cy={size / 2}
          r={radius}
          strokeWidth={strokeWidth}
        />
        <circle
          className="progress-circle-fill"
          cx={size / 2}
          cy={size / 2}
          r={radius}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          stroke={color}
        />
      </svg>
      <span className="progress-circle-label">{`${Math.round(percentage)}%`}</span>
    </div>
  );
};

export default ProgressCircle;

