import React, { useState } from 'react';
import './Notification.css';

type NotificationType = 'info' | 'success' | 'warning' | 'error';

interface NotificationProps {
  id: string;
  type: NotificationType;
  title: string;
  message: string;
  timestamp: Date;
  isRead?: boolean;
  onDismiss?: (id: string) => void;
}

const Notification: React.FC<NotificationProps> = ({
  id,
  type,
  title,
  message,
  timestamp,
  isRead = false,
  onDismiss,
}) => {
  const [isHovered, setIsHovered] = useState(false);

  const handleDismiss = () => {
    if (onDismiss) onDismiss(id);
  };

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <div
      className={`notification ${type} ${isRead ? 'read' : 'unread'}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="notification-icon">
        {type === 'info' && <i className="fas fa-info-circle"></i>}
        {type === 'success' && <i className="fas fa-check-circle"></i>}
        {type === 'warning' && <i className="fas fa-exclamation-triangle"></i>}
        {type === 'error' && <i className="fas fa-times-circle"></i>}
      </div>
      <div className="notification-content">
        <div className="notification-header">
          <h4>{title}</h4>
          <span className="notification-time">{formatTime(timestamp)}</span>
        </div>
        <p>{message}</p>
      </div>
      {isHovered && (
        <button className="notification-dismiss" onClick={handleDismiss}>
          <i className="fas fa-times"></i>
        </button>
      )}
    </div>
  );
};

export default Notification;

import React, { useState } from 'react';
import Notification from './Notification';
import './Notification.css';

interface NotificationItem {
  id: string;
  type: 'info' | 'success' | 'warning' | 'error';
  title: string;
  message: string;
  timestamp: Date;
  isRead: boolean;
}

const NotificationList: React.FC = () => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([
    {
      id: '1',
      type: 'success',
      title: 'Payment Received',
      message: 'Your payment of $249.00 has been processed successfully.',
      timestamp: new Date(Date.now() - 1000 * 60 * 5),
      isRead: false,
    },
    {
      id: '2',
      type: 'info',
      title: 'New Feature Available',
      message: 'Check out our new dashboard analytics feature now live!',
      timestamp: new Date(Date.now() - 1000 * 60 * 30),
      isRead: true,
    },
    {
      id: '3',
      type: 'warning',
      title: 'Scheduled Maintenance',
      message: 'System maintenance scheduled for tomorrow at 2:00 AM EST.',
      timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2),
      isRead: false,
    },
    {
      id: '4',
      type: 'error',
      title: 'Login Attempt Failed',
      message: 'There was an unsuccessful login attempt to your account.',
      timestamp: new Date(Date.now() - 1000 * 60 * 60 * 24),
      isRead: true,
    },
  ]);

  const [showUnreadOnly, setShowUnreadOnly] = useState(false);

  const handleDismiss = (id: string) => {
    setNotifications(notifications.filter((n) => n.id !== id));
  };

  const markAllAsRead = () => {
    setNotifications(
      notifications.map((n) => ({
        ...n,
        isRead: true,
      }))
    );
  };

  const filteredNotifications = showUnreadOnly
    ? notifications.filter((n) => !n.isRead)
    : notifications;

  return (
    <div className="notification-list">
      <div className="notification-list-header">
        <h3>Notifications</h3>
        <div className="notification-list-actions">
          <button
            className={`filter-toggle ${showUnreadOnly ? 'active' : ''}`}
            onClick={() => setShowUnreadOnly(!showUnreadOnly)}
          >
            {showUnreadOnly ? 'Show All' : 'Unread Only'}
          </button>
          <button className="mark-all-read" onClick={markAllAsRead}>
            Mark All as Read
          </button>
        </div>
      </div>
      <div className="notification-list-items">
        {filteredNotifications.length > 0 ? (
          filteredNotifications.map((notification) => (
            <Notification
              key={notification.id}
              {...notification}
              onDismiss={handleDismiss}
            />
          ))
        ) : (
          <div className="empty-notifications">
            No notifications to display
          </div>
        )}
      </div>
    </div>
  );
};

export default NotificationList;

import React, { useState, useEffect } from 'react';
import NotificationList from './NotificationList';
import './Notification.css';

const NotificationCenter: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  // Simulate receiving new notifications
  useEffect(() => {
    const interval = setInterval(() => {
      const shouldAddNotification = Math.random() > 0.7;
      if (shouldAddNotification) {
        setUnreadCount((prev) => prev + 1);
      }
    }, 30000); // Every 30 seconds

    return () => clearInterval(interval);
  }, []);

  const handleNotificationClick = () => {
    setIsOpen(!isOpen);
    if (unreadCount > 0) {
      setUnreadCount(0);
    }
  };

  return (
    <div className="notification-center">
      <div
        className="notification-bell"
        onClick={handleNotificationClick}
        data-count={unreadCount > 0 ? unreadCount : null}
      >
        <i className="fas fa-bell"></i>
      </div>
      {isOpen && (
        <div className="notification-dropdown">
          <NotificationList />
        </div>
      )}
    </div>
  );
};

export default NotificationCenter;

