import React, { useState, useEffect } from 'react';
import './MapComponent.css';

interface Location {
  id: number;
  name: string;
  coordinates: [number, number];
  visitors: number;
  status: 'active' | 'inactive';
}

export const MapComponent = () => {
  const [locations, setLocations] = useState<Location[]>([
    { id: 1, name: 'New York Office', coordinates: [40.7128, -74.006], visitors: 1245, status: 'active' },
    { id: 2, name: 'London Branch', coordinates: [51.5074, -0.1278], visitors: 892, status: 'active' },
    { id: 3, name: 'Tokyo Center', coordinates: [35.6762, 139.6503], visitors: 1567, status: 'inactive' },
  ]);

  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null);
  const [zoomLevel, setZoomLevel] = useState<number>(5);

  const handleMarkerClick = (location: Location) => {
    setSelectedLocation(location);
    setZoomLevel(10);
  };

  return (
    <div className="map-container">
      <div className="map-controls">
        <button onClick={() => setZoomLevel(prev => Math.min(prev + 1, 15))}>Zoom In</button>
        <button onClick={() => setZoomLevel(prev => Math.max(prev - 1, 1))}>Zoom Out</button>
      </div>

      <div className="map-display">
        {/* This would be replaced with actual map library implementation */}
        <div className="map-placeholder">
          <h3>Interactive Map (Zoom: {zoomLevel}x)</h3>
          {locations.map(location => (
            <div 
              key={location.id} 
              className={`map-marker ${location.status} ${selectedLocation?.id === location.id ? 'selected' : ''}`}
              onClick={() => handleMarkerClick(location)}
            >
              {location.name}
              <span className="visitor-count">{location.visitors} visitors</span>
            </div>
          ))}
        </div>
      </div>

      {selectedLocation && (
        <div className="location-details">
          <h4>{selectedLocation.name}</h4>
          <p>Coordinates: {selectedLocation.coordinates.join(', ')}</p>
          <p>Status: {selectedLocation.status}</p>
          <p>Monthly Visitors: {selectedLocation.visitors}</p>
        </div>
      )}
    </div>
  );
};

