import React, { useState } from 'react';
import './Table.css';

type User = {
  id: number;
  name: string;
  email: string;
  role: string;
  lastActive: string;
};

type Product = {
  id: number;
  name: string;
  category: string;
  price: number;
  stock: number;
};

type Order = {
  id: string;
  customer: string;
  date: string;
  amount: number;
  status: 'Pending' | 'Shipped' | 'Delivered';
};

const Table = () => {
  const [activeTab, setActiveTab] = useState<'users' | 'products' | 'orders'>('users');

  // Mock data
  const users: User[] = [
    { id: 1, name: 'Alex Johnson', email: 'alex.johnson@example.com', role: 'Admin', lastActive: '2 hours ago' },
    { id: 2, name: 'Maria Garcia', email: 'maria.g@example.com', role: 'Editor', lastActive: '1 day ago' },
    { id: 3, name: 'James Wilson', email: 'james.w@example.com', role: 'Viewer', lastActive: '3 days ago' },
  ];

  const products: Product[] = [
    { id: 101, name: 'Wireless Headphones', category: 'Electronics', price: 99.99, stock: 45 },
    { id: 102, name: 'Organic Cotton T-Shirt', category: 'Apparel', price: 29.99, stock: 120 },
    { id: 103, name: 'Stainless Steel Water Bottle', category: 'Accessories', price: 24.95, stock: 78 },
  ];

  const orders: Order[] = [
    { id: 'ORD-1001', customer: 'Alex Johnson', date: '2023-05-15', amount: 149.98, status: 'Shipped' },
    { id: 'ORD-1002', customer: 'Sarah Miller', date: '2023-05-16', amount: 54.94, status: 'Pending' },
    { id: 'ORD-1003', customer: 'David Kim', date: '2023-05-14', amount: 99.99, status: 'Delivered' },
  ];

  const renderTable = () => {
    switch (activeTab) {
      case 'users':
        return (
          <table className="user-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>Role</th>
                <th>Last Active</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr key={user.id}>
                  <td>{user.id}</td>
                  <td>{user.name}</td>
                  <td>{user.email}</td>
                  <td>{user.role}</td>
                  <td>{user.lastActive}</td>
                </tr>
              ))}
            </tbody>
          </table>
        );
      case 'products':
        return (
          <table className="product-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Category</th>
                <th>Price</th>
                <th>Stock</th>
              </tr>
            </thead>
            <tbody>
              {products.map((product) => (
                <tr key={product.id}>
                  <td>{product.id}</td>
                  <td>{product.name}</td>
                  <td>{product.category}</td>
                  <td>${product.price.toFixed(2)}</td>
                  <td>{product.stock}</td>
                </tr>
              ))}
            </tbody>
          </table>
        );
      case 'orders':
        return (
          <table className="order-table">
            <thead>
              <tr>
                <th>Order ID</th>
                <th>Customer</th>
                <th>Date</th>
                <th>Amount</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((order) => (
                <tr key={order.id}>
                  <td>{order.id}</td>
                  <td>{order.customer}</td>
                  <td>{order.date}</td>
                  <td>${order.amount.toFixed(2)}</td>
                  <td>
                    <span className={`status-badge ${order.status.toLowerCase()}`}>
                      {order.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        );
      default:
        return null;
    }
  };

  return (
    <div className="table-container">
      <h2>Data Tables</h2>
      <div className="tabs">
        <button
          className={activeTab === 'users' ? 'active' : ''}
          onClick={() => setActiveTab('users')}
        >
          Users
        </button>
        <button
          className={activeTab === 'products' ? 'active' : ''}
          onClick={() => setActiveTab('products')}
        >
          Products
        </button>
        <button
          className={activeTab === 'orders' ? 'active' : ''}
          onClick={() => setActiveTab('orders')}
        >
          Orders
        </button>
      </div>
      {renderTable()}
    </div>
  );
};

export default Table;

