import React from 'react';
import './Timeline.css';

type TimelineEvent = {
  id: string;
  title: string;
  description: string;
  date: string;
  icon: string;
  color: string;
};

interface TimelineProps {
  events: TimelineEvent[];
  variant?: 'default' | 'compact' | 'interactive';
}

const Timeline: React.FC<TimelineProps> = ({ events, variant = 'default' }) => {
  const [activeEvent, setActiveEvent] = React.useState<string | null>(null);

  const handleEventClick = (id: string) => {
    if (variant === 'interactive') {
      setActiveEvent(activeEvent === id ? null : id);
    }
  };

  return (
    <div className={`timeline ${variant}`}>
      {events.map((event) => (
        <div 
          key={event.id} 
          className={`timeline-event ${activeEvent === event.id ? 'active' : ''}`}
          onClick={() => handleEventClick(event.id)}
        >
          <div className="timeline-marker" style={{ backgroundColor: event.color }}>
            <span className="material-icons">{event.icon}</span>
          </div>
          <div className="timeline-content">
            <h4>{event.title}</h4>
            <p className="timeline-date">{event.date}</p>
            {(variant !== 'compact' || activeEvent === event.id) && (
              <p className="timeline-description">{event.description}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

export default Timeline;

